// Component: Newsletter */
// ==================== */

class NewsletterComponent {
    constructor() {
        this.form = document.getElementById('newsletter-form');
        if (this.form) {
            this.form.addEventListener('submit', (e) => this.handleSubmit(e));
        }
    }

    handleSubmit(e) {
        e.preventDefault();
        const email = this.form.querySelector('input[type="email"]').value;
        console.log('Newsletter subscription:', email);
        this.form.innerHTML = '<p style="color: white; margin: 0;">✓ Thanks for subscribing!</p>';
        setTimeout(() => {
            this.form.innerHTML = `<input type="email" placeholder="Enter your email" required><button type="submit" class="btn btn--primary">Subscribe</button>`;
            this.form.addEventListener('submit', (e) => this.handleSubmit(e));
        }, 3000);
    }
}

// ==================== */
// Component: Favorites */
// ==================== */

class FavoritesComponent {
    constructor() {
        this.favorites = new Set(JSON.parse(localStorage.getItem('favorites')) || []);
        this.initFavoriteButtons();
    }

    initFavoriteButtons() {
        const buttons = document.querySelectorAll('.product-card .btn--icon');
        buttons.forEach((button, index) => {
            const productCard = button.closest('.product-card');
            const productName = productCard.querySelector('h3').textContent;
            const productId = `product-${index}`;

            if (this.favorites.has(productId)) {
                button.textContent = '♥';
                button.style.color = '#ff6b6b';
            }

            button.addEventListener('click', () => this.toggleFavorite(productId, button));
        });
    }

    toggleFavorite(productId, button) {
        if (this.favorites.has(productId)) {
            this.favorites.delete(productId);
            button.textContent = '♡';
            button.style.color = 'inherit';
        } else {
            this.favorites.add(productId);
            button.textContent = '♥';
            button.style.color = '#ff6b6b';
        }
        this.saveFavorites();
    }

    saveFavorites() {
        localStorage.setItem('favorites', JSON.stringify(Array.from(this.favorites)));
    }
}

// ==================== */
// Component: Analytics */
// ==================== */

class AnalyticsComponent {
    constructor() {
        this.trackPageLoad();
        this.trackNavigationClicks();
        this.trackButtonClicks();
    }

    trackPageLoad() {
        console.log('📊 Page loaded:', {
            timestamp: new Date().toISOString(),
            url: window.location.href,
            userAgent: navigator.userAgent.substring(0, 50)
        });
    }

    trackNavigationClicks() {
        const navLinks = document.querySelectorAll('.navbar__menu a');
        navLinks.forEach(link => {
            link.addEventListener('click', () => {
                console.log('📍 Navigation:', link.textContent);
            });
        });
    }

    trackButtonClicks() {
        const ctaButtons = document.querySelectorAll('.btn--primary, .btn--secondary');
        ctaButtons.forEach(button => {
            button.addEventListener('click', () => {
                console.log('🔘 Button clicked:', button.textContent.trim());
            });
        });
    }
}

// ==================== */
// Initialization        */
// ==================== */

document.addEventListener('DOMContentLoaded', () => {
    new NewsletterComponent();
    new FavoritesComponent();
    new AnalyticsComponent();

    console.log('✅ ModernRetail homepage ready');
});
